import { NextRequest } from 'next/server';
import { createReadStream } from 'fs';
import { stat } from 'fs/promises';
import path from 'path';
import { existsSync } from 'fs';

export async function GET(
  request: NextRequest,
  { params }: { params: { path: string[] } }
) {
  try {
    // Get the path from the URL
    const filePath = params.path?.join('/');
    
    if (!filePath) {
      return new Response('Not Found', { status: 404 });
    }
    
    // Construct the full path to the file (ensure we're only accessing files in the uploads directory)
    const fullPath = path.join(process.cwd(), '..', 'uploads', filePath);
    
    // Security check to make sure we're not serving files outside the uploads directory
    const normalizedFullPath = path.normalize(fullPath);
    const uploadsDir = path.join(process.cwd(), '..', 'uploads');
    
    if (!normalizedFullPath.startsWith(uploadsDir)) {
      return new Response('Forbidden', { status: 403 });
    }
    
    // Check if the file exists
    if (!existsSync(normalizedFullPath)) {
      return new Response('Not Found', { status: 404 });
    }
    
    // Get file stats to determine size
    const fileStat = await stat(normalizedFullPath);
    
    // Determine content type based on file extension
    const ext = path.extname(normalizedFullPath).toLowerCase();
    let contentType = 'application/octet-stream'; // Default content type
    
    // Set proper content type based on file extension
    if (ext === '.jpg' || ext === '.jpeg') {
      contentType = 'image/jpeg';
    } else if (ext === '.png') {
      contentType = 'image/png';
    } else if (ext === '.gif') {
      contentType = 'image/gif';
    } else if (ext === '.webp') {
      contentType = 'image/webp';
    }
    
    // Create a readable stream for the file
    const fileStream = createReadStream(normalizedFullPath);
    
    // Return the file as a stream
    return new Response(fileStream as unknown as ReadableStream, {
      headers: {
        'Content-Type': contentType,
        'Content-Length': fileStat.size.toString(),
        'Cache-Control': 'public, max-age=300',
      },
    });
  } catch (error) {
    console.error('Error serving static file:', error);
    return new Response('Internal Server Error', { status: 500 });
  }
}